// CSD_RATIONALE_BEGIN
// Root cause of 52% ceiling (attempt 43): The early `IsCompletePrefix` check in
// Phase 3 fires at the FIRST syntactically complete SQL prefix
// (e.g. "SELECT city FROM employee"), immediately closing the span and preventing
// the model from appending WHERE/GROUP BY/HAVING/ORDER BY/LIMIT clauses.
// This explains truncated outputs like "SELECT city" (no WHERE/GROUP BY/HAVING)
// and "SELECT COUNT(DISTINCT year) FROM cars" (no WHERE) seen in the rollouts.
//
// Fix: Remove the early IsCompletePrefix close from Phase 3. Let GroupBoostedConstrainedStep
// with boost=6.0 (which gave 99% syntax in attempt 43) continue until the model
// naturally emits EOS, indicating it has written the full intended query.
// CloseSpanWithinBudget in Phase 4 then closes at the LONGEST complete prefix,
// which includes all clauses the model generated before EOS.
//
// Structural choices:
// 1. NO early IsCompletePrefix close – model can generate all clauses freely.
// 2. Boost=6.0 – restored from attempt 43 to recover 99% syntax (attempt 51
//    dropped to 85.7% by reducing to 2.0).
// 3. Phase 4 CloseSpanWithinBudget budget=min(remaining,300) – larger than 80
//    to handle full-clause SQL queries that need extra tokens to complete.
// 4. Task guidance emphasises generating complete queries with all necessary
//    clauses instead of stopping at the first minimal valid SQL.
// 5. RenderedEndsWith for delimiter detection, 5-step free preamble,
//    forced OpenConstrainedSpan – all preserved from attempt 43.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble (guard !insideConstrainedOut):
//   insideConstrainedOut flips true only on RenderedEndsWith, which sets
//   currentConstrainedOut := []. IsValidPrefix([]) holds by method precondition.
//   On EOS break insideConstrainedOut stays false; implication is vacuous.
//
// Phase 2 OpenConstrainedSpan (guarded by !insideConstrainedOut):
//   Helper sets currentConstrainedOut := []. IsValidPrefix([]) by precondition.
//
// Phase 3 constrained loop (no early close):
//   GroupBoostedConstrainedStep hard-masks to parser-valid tokens plus EOS; it
//   never returns a parser-invalid non-EOS token. On non-EOS,
//   AppendConstrainedToken extends currentConstrainedOut by exactly one
//   parser-valid token, preserving IsValidPrefix by the monotone extension
//   contract of the parser. On EOS break, currentConstrainedOut is not modified;
//   it retains the last valid value. insideConstrainedOut stays true throughout
//   Phase 3 (no close call), so the invariant is maintained at every loop exit.
//
// Phase 4 CloseSpanWithinBudget:
//   Postcondition guarantees !insideOut ==> currentOut == [] and
//   insideOut ==> parser.IsValidPrefix(currentOut). Both branches preserve the
//   invariant without further proof obligation on the caller side.
//
// Invariant 2: progress  |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs +1 step; appends at most 1 token (0 on EOS,
//   1 on non-EOS). Each iteration: |generated| grows by at most 1, steps by 1.
//
// Phase 2: OpenConstrainedSpan costs +1 step and appends exactly 1 "<<" token.
//   Net 1:1.
//
// Phase 3: GroupBoostedConstrainedStep costs +1 step (steps += 1 per iteration).
//   AppendConstrainedToken appends exactly 1 token on non-EOS; 0 tokens on EOS
//   break. So |generated| grows by at most 1 while steps grows by exactly 1.
//   Invariant is preserved at every loop iteration.
//
// Phase 4: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated| +
//   closeBudget. We set steps := steps_before + closeBudget where
//   closeBudget = min(maxSteps - steps_before, 300) <= maxSteps - steps_before.
//   Therefore steps_after <= maxSteps and
//   |generated_after| <= |generatedPrefix| + steps_after. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate the complete SQL SELECT that fully answers the question. CRITICAL: include ALL necessary clauses - WHERE, GROUP BY, HAVING, ORDER BY, LIMIT - that the question requires. Do not stop at a minimal valid SQL. For 'how many' questions use COUNT(*); for 'which/what values' questions return the actual column values. Use ONLY exact table and column names from the provided schema. Format: SQL: <<complete_query>>");

var steps: nat := 0;

// Phase 1: Short free preamble (at most 5 steps) to let model emit "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard parser control with schema-group boosting (6.0).
// KEY CHANGE FROM ATTEMPT 43: NO early IsCompletePrefix close.
// The model continues generating tokens past the first complete SQL prefix,
// allowing it to append WHERE/GROUP BY/HAVING/ORDER BY/LIMIT clauses before
// choosing EOS. CloseSpanWithinBudget in Phase 4 closes at the longest complete
// prefix found after the model has finished its natural generation.
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next := helpers.GroupBoostedConstrainedStep(
    lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
  );
  steps := steps + 1;
  if next == eosToken {
    // Model is satisfied with the current SQL; exit and let Phase 4 close cleanly.
    break;
  } else {
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

// Phase 4: Close the span if still open after Phase 3 EOS exit.
// CloseSpanWithinBudget closes at the longest complete prefix of currentConstrainedOut,
// generating additional tokens only if needed to reach a completable state.
// When the model already produced a full query (IsCompletePrefix true), this
// closes in ~1 step by appending ">>".
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 300 {
    closeBudget := remaining;
  } else {
    closeBudget := 300;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

